from functools import cmp_to_key

def _parse_version(s):
    if s.startswith('v'):
        s = s[1:]
    if not s:
        raise ValueError("Empty version string")

    parts = s.split('-', 1)
    main_part = parts[0]
    pre_part = parts[1] if len(parts) > 1 else None

    if pre_part == "":
        raise ValueError("Empty pre-release part")

    main_version_parts = []
    for p in main_part.split('.'):
        if not p:
            raise ValueError("Empty part in version")
        if not p.isdigit():
            raise ValueError("Non-numeric part in version")
        main_version_parts.append(int(p))

    pre_release_parts = []
    if pre_part:
        chunks = re.findall(r'[a-zA-Z]+|\d+', pre_part)
        if "".join(chunks) != pre_part:
             raise ValueError("Invalid characters in pre-release")

        for chunk in chunks:
            if chunk.isdigit():
                pre_release_parts.append(int(chunk))
            else:
                pre_release_parts.append(chunk)

    return main_version_parts, pre_release_parts

def _compare_pre_releases(pre1, pre2):
    for p1, p2 in zip(pre1, pre2):
        if type(p1) != type(p2):
            s1, s2 = str(p1), str(p2)
            if s1 < s2: return -1
            if s1 > s2: return 1
            continue

        if p1 < p2: return -1
        if p1 > p2: return 1

    if len(pre1) < len(pre2): return -1
    if len(pre1) > len(pre2): return 1
    return 0

def compare(a, b):
    """Return -1 if a < b, 0 if they are equal, 1 if a > b."""
    main_a, pre_a = _parse_version(a)
    main_b, pre_b = _parse_version(b)

    max_len = max(len(main_a), len(main_b))
    for i in range(max_len):
        v_a = main_a[i] if i < len(main_a) else 0
        v_b = main_b[i] if i < len(main_b) else 0
        if v_a < v_b: return -1
        if v_a > v_b: return 1

    if not pre_a and pre_b:
        return 1
    if pre_a and not pre_b:
        return -1
    if not pre_a and not pre_b:
        return 0

    return _compare_pre_releases(pre_a, pre_b)


def latest(versions):
    """The newest version in the list."""
    return max(versions, key=cmp_to_key(compare))
